/** * WakeOnLan Win10 (Custom) * Platform: Hubitat Elevation * Notes: Manages and triggers Wake on LAN magic packets for network devices. * Category: Utility **//** * Copyright 2026 James Shimota * * Licensed under the Apache License, Version 2.0 (the "License"); * you may not use this file except in compliance with the License. * You may obtain a copy of the License at: * *     http://www.apache.org/licenses/LICENSE-2.0 * * Unless required by applicable law or agreed to in writing, software * distributed under the License is distributed on an "AS IS" BASIS, * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied. * See the License for the specific language governing permissions and * limitations under the License. **//** *  Purpose: *  Manages Wake-on-LAN target devices, handles child device creation, and provides centralized configuration. * *  Instructions: *  1. Install this app and the matching WakeOnLan Win10 (Custom) driver. *  2. Add WOL targets via the app UI or manually configure individual child devices. *   *  Changelog: *  v1.0.3   09/17/26   jshimota   Updated app definition name and comments to WakeOnLan Win10 (Custom). *  v1.0.2   09/17/26   jshimota   Added configureUseSecureOn setting; default UDP Port updated to 9; updated Port labels to UDP Port. *	v1.0.1	  09/10/26	  jshimota	  Fixed version change detection bug, added pre-creation field validation, enhanced diagnostic logging. *	v1.0.0	  09/10/26	  jshimota	  Initial release based on standardized template architecture. **/static String version() { return '1.0.3' }def timeStamp() { return "2026/09/17 08:35 AM" }definition(    name: "WakeOnLan Win10 (Custom)",    namespace: "jshimota",    author: "James Shimota",    description: "Manage and trigger Wake-on-LAN magic packets across LAN targets.",    category: "Utility",    iconUrl: "",    iconX2Url: "",    iconX3Url: "",    importUrl: "")preferences {    page(name: "mainPage")    page(name: "configureDevicePage")}def mainPage() {    dynamicPage(name: "mainPage", title: "", install: true, uninstall: true) {        String currentVersion = version()        /* Styled App Header Banner */        section() {            paragraph "<div style='background-color:#1A252F; color:#FFFFFF; padding:12px; border-radius:6px; text-align:center; margin-bottom:10px;'>" +                      "<h2 style='color:#FFFFFF; margin:0; font-size:20px; font-weight:600;'>WakeOnLan Win10 (Custom)</h2>" +                      "<span style='font-size:12px; opacity:0.8;'>Version ${currentVersion} (${timeStamp()})</span></div>"        }        section("<b>WOL Target Devices</b>") {            getChildDevices().sort({ a, b -> a.label <=> b.label }).each { dev ->                String mac = dev.getDataValue("MAC") ?: "No MAC"                href(                    name: "configureDevicePage_${dev.deviceNetworkId}",                    title: "${dev.label} [${mac}]",                    description: "Click to configure",                    params: [deviceNetworkId: dev.deviceNetworkId],                    page: "configureDevicePage"                )            }            href(                name: "addDeviceLink",                title: "<font size='4'>➕ Add WOL Device</font>",                description: "Click to add a new Wake-on-LAN target",                page: "configureDevicePage"            )        }        /* Collapsible App Preferences & Logging Options */        section("<b>App Preferences & Logging Options</b>", hideable: true, hidden: true) {            input name: "showVersionInLabel", type: "bool", title: "Show Version in App Label?", defaultValue: true            paragraph "<hr style='border:0; border-top:1px solid #E0E0E0; margin:8px 0;'/>"            input name: "logInfoEnable", type: "bool", title: "Logging - Enable Info Logging", defaultValue: true, required: true            input name: "logErrorEnable", type: "bool", title: "Logging - Enable Error Logging", defaultValue: true, required: true            input name: "logWarnEnable", type: "bool", title: "Logging - Enable Warning Logging", defaultValue: true, required: true            input name: "logDebugEnable", type: "bool", title: "Logging - Enable Debug Logging", defaultValue: false, required: true            input name: "logTraceEnable", type: "bool", title: "Logging - Enable Trace Logging", defaultValue: false, required: true        }    }}def configureDevicePage(params) {    if (state.deleted) {        state.deleted = false        return mainPage()    }    String editId = params?.deviceNetworkId ?: state.editedId    state.editedId = editId    if (editId == null) {        return dynamicPage(name: "configureDevicePage", title: "Add New WOL Device", install: false, uninstall: false) {            section("<b>Device Details</b>") {                input "configureDeviceName", "text", title: "Device Name", required: true                input "configureMACAddress", "text", title: "MAC Address", required: true                input "configureIP", "text", title: "IP Address", description: "Default: 255.255.255.255 (Subnet Broadcast)", required: false                input "configurePort", "number", title: "UDP Port", description: "Default: 9", required: false, defaultValue: 9                input "configureUseSecureOn", "bool", title: "Use SecureOn Password?", required: false, defaultValue: false                input "configureSecureOn", "text", title: "SecureOn Password", description: "12-character hex password (optional)", required: false            }        }    } else {        def device = getChildDevice(editId)        return dynamicPage(name: "configureDevicePage", title: "Configure ${device?.label}", install: false, uninstall: false) {            section("<b>Device Details</b>") {                input "configureDeviceName", "text", title: "Device Name", required: true, defaultValue: device?.label                input "configureMACAddress", "text", title: "MAC Address", required: true, defaultValue: device?.getDataValue("MAC")                input "configureIP", "text", title: "IP Address", required: false, defaultValue: device?.getDataValue("IP")                input "configurePort", "number", title: "UDP Port", required: false, defaultValue: device?.getDataValue("Port") ?: 9                input "configureUseSecureOn", "bool", title: "Use SecureOn Password?", required: false, defaultValue: device?.getSetting("useSecureOn") ?: false                input "configureSecureOn", "text", title: "SecureOn Password", required: false, defaultValue: device?.getDataValue("SecureOn")                input "removeDeviceBTN", "button", title: "Remove Device"            }        }    }}void appButtonHandler(String btn) {    if (btn == "removeDeviceBTN" && state.editedId) {        logInfo "Removing target device Network ID: ${state.editedId}"        deleteChildDevice(state.editedId)        clearDeviceConfigSettings()        state.editedId = null        state.deleted = true    }}private void clearDeviceConfigSettings() {    app.clearSetting("configureDeviceName")    app.clearSetting("configureMACAddress")    app.clearSetting("configureIP")    app.clearSetting("configurePort")    app.clearSetting("configureUseSecureOn")    app.clearSetting("configureSecureOn")}private void checkAndLogVersionDemarcation() {    String currentVer = version()    if (state.appVersion != currentVer) {        logTrace "=================== APP VERSION UPDATE: v${currentVer} (${timeStamp()}) ==================="        state.appVersion = currentVer    }}private void updateAppLabel() {    Boolean showVersion = getSettingBool("showVersionInLabel", true)    String baseLabel = "WakeOnLan Win10 (Custom)"    if (showVersion) baseLabel += " v${version()}"    if (app.label != baseLabel) {        app.updateLabel(baseLabel)    }}private String captureSettingsSnapshot() {    Map snapshot = [:]    List<String> sortedKeys = settings.keySet()        .collect { it.toString() }        .findAll { k -> !(k == "label" || k.startsWith("btn")) }        .sort()    sortedKeys.each { k -> snapshot[k] = settings[k]?.toString() }    String jsonString = groovy.json.JsonOutput.toJson(snapshot)    return java.security.MessageDigest.getInstance("MD5").digest(jsonString.bytes).encodeHex().toString()}void installed() {    checkAndLogVersionDemarcation()    logInfo "Installing app v${version()} (${timeStamp()})..."    state.lastSettingsSnapshot = captureSettingsSnapshot()    initialize(true)}void updated() {    Boolean codeVersionChanged = (state.appVersion != version())    checkAndLogVersionDemarcation()    logInfo "Updating app configuration..."    if (state.editedId != null || settings.configureDeviceName != null) {        saveDeviceConfig()    }    String currentSnapshot = captureSettingsSnapshot()    Boolean settingsChanged = (state.lastSettingsSnapshot == null || state.lastSettingsSnapshot != currentSnapshot)    if (settingsChanged || codeVersionChanged) {        logInfo "Settings or code version modification detected."        state.lastSettingsSnapshot = currentSnapshot    }    updateAppLabel()}private String normalizeMac(String mac) {    if (!mac) return null    String normalized = mac.replaceAll(/[^0-9A-Fa-f]/, '').toUpperCase()    return (normalized ==~ /[0-9A-F]{12}/) ? normalized : null}private void saveDeviceConfig() {    if (!configureDeviceName || !configureMACAddress) {        logWarn "Cannot save WOL device: required configuration (Name or MAC) is missing."        return    }    String cleanMac = normalizeMac(configureMACAddress)    if (!cleanMac) {        logError "Cannot save WOL device '${configureDeviceName}': Invalid MAC address '${configureMACAddress}'."        return    }    Integer port = configurePort ? configurePort.toInteger() : 9    if (port < 1 || port > 65535) {        logError "Cannot save WOL device '${configureDeviceName}': Invalid UDP port '${configurePort}'."        return    }    String targetIp = configureIP ?: "255.255.255.255"    Boolean useSecOn = (configureUseSecureOn != null) ? configureUseSecureOn : false    String secOnStatus = (useSecOn && configureSecureOn) ? "configured" : "disabled/not configured"    if (state.editedId == null) {        try {            def newDevice = addChildDevice(                "jshimota",                "WakeOnLan Win10 (Custom)",                "WOL_" + now(),                [label: configureDeviceName, isComponent: false]            )            newDevice.updateSetting("myMac", [type: "text", value: cleanMac])            newDevice.updateSetting("myPort", [type: "number", value: port])            newDevice.updateSetting("myIP", [type: "text", value: targetIp])            newDevice.updateSetting("useSecureOn", [type: "bool", value: useSecOn])            newDevice.updateSetting("mySecureOn", [type: "text", value: configureSecureOn ?: ""])            newDevice.updated()            logInfo "Created WOL target device '${configureDeviceName}': MAC=${cleanMac}, IP=${targetIp}, UDP Port=${port}, SecureOn=${secOnStatus}"        } catch (Exception e) {            logError "Failed to create WOL child device: ${e.message}"        }    } else {        def device = getChildDevice(state.editedId)        if (device) {            device.updateSetting("myMac", [type: "text", value: cleanMac])            device.updateSetting("myPort", [type: "number", value: port])            device.updateSetting("myIP", [type: "text", value: targetIp])            device.updateSetting("useSecureOn", [type: "bool", value: useSecOn])            device.updateSetting("mySecureOn", [type: "text", value: configureSecureOn ?: ""])            device.label = configureDeviceName            device.updated()            logInfo "Updated WOL target device '${configureDeviceName}': MAC=${cleanMac}, IP=${targetIp}, UDP Port=${port}, SecureOn=${secOnStatus}"        }    }    state.editedId = null    clearDeviceConfigSettings()}void uninstalled() {    logInfo "Uninstalling app..."    unsubscribe()    unschedule()}private void initialize(Boolean isInstall = false) {    checkAndLogVersionDemarcation()    updateAppLabel()    if (isInstall) {        app.updateSetting("logDebugEnable", [type: "bool", value: true])        logInfo "Debug logging enabled for 30 minutes."        runIn(1800, "disableDebugLogging")    } else if (getSettingBool("logDebugEnable", false)) {        runIn(1800, "disableDebugLogging", [overwrite: false])    } else {        unschedule("disableDebugLogging")    }}void disableDebugLogging() {    if (getSettingBool("logDebugEnable", false)) {        logWarn "30 minutes have elapsed. Automatically disabling debug logging."        app.updateSetting("logDebugEnable", [type: "bool", value: false])    }}private void logMessage(String level, String msg) {    String lowerLevel = level?.toLowerCase() ?: "info"    String appLabel = app.label ?: app.name ?: "App"    String settingKey = "log${lowerLevel.capitalize()}Enable"    Boolean defaultEnabled = (lowerLevel in ["info", "warn", "error"])    if (getSettingBool(settingKey, defaultEnabled)) {        log."${lowerLevel}" "${appLabel}: ${msg}"    }}private void logInfo(String msg)  { logMessage("info", msg) }private void logDebug(String msg) { logMessage("debug", msg) }private void logTrace(String msg) { logMessage("trace", msg) }private void logWarn(String msg)  { logMessage("warn", msg) }private void logError(String msg) { logMessage("error", msg) }private Boolean getSettingBool(String key, Boolean defaultVal = false) {    def val = settings[key]    if (val == null) return defaultVal    if (val instanceof Boolean) return val    return val.toString().toBoolean()}